<?php
require_once __DIR__.'/lib/common.php';
if (!$user->hasRight('creditlimit','audit')) accessforbidden();
$rows=$cl->rows('SELECT l.*,s.nom,u.login,u.firstname,u.lastname FROM '.$cl->table('cl_check_log').' l LEFT JOIN '.$cl->table('societe').' s ON s.rowid=l.fk_soc LEFT JOIN '.$cl->table('user').' u ON u.rowid=l.fk_user WHERE l.entity='.$cl->entity.' ORDER BY l.date_check DESC,l.rowid DESC LIMIT 500');
clHeader('Credit Control Audit');
print '<div class="cl-scroll"><table class="noborder centpercent cl-table"><tr class="liste_titre"><th>Waktu</th><th>Customer</th><th>Dokumen</th><th>Keputusan</th><th class="right">Exposure</th><th class="right">Dokumen</th><th class="right">Projected</th><th class="right">Limit</th><th>Overdue</th><th>Alasan</th><th>User</th></tr>';
foreach($rows as $r){$name=trim($r->firstname.' '.$r->lastname)?:$r->login; print '<tr class="oddeven"><td>'.clEscape(dol_print_date($db->jdate($r->date_check),'dayhour')).'</td><td>'.clEscape($r->nom).'</td><td>'.clEscape($r->element_type.' — '.$r->element_ref).'</td><td><span class="cl-status cl-'.clEscape($r->decision).'">'.clEscape(strtoupper($r->decision)).'</span></td><td class="right">'.clMoney($r->exposure).'</td><td class="right">'.clMoney($r->document_amount).'</td><td class="right">'.clMoney($r->projected_exposure).'</td><td class="right">'.clMoney($r->credit_limit).'</td><td>'.clMoney($r->overdue_amount).' / '.$r->oldest_overdue_days.' hari</td><td>'.clEscape($r->reason).'</td><td>'.clEscape($name).'</td></tr>';}
if(!$rows)print '<tr><td colspan="11" class="center">Belum ada keputusan credit control.</td></tr>'; print '</table></div>';
$approvals=$cl->rows('SELECT o.*,s.nom,u.login,u.firstname,u.lastname FROM '.$cl->table('cl_override').' o LEFT JOIN '.$cl->table('societe').' s ON s.rowid=o.fk_soc LEFT JOIN '.$cl->table('user').' u ON u.rowid=o.fk_user_approve WHERE o.entity='.$cl->entity.' ORDER BY o.date_approve DESC,o.rowid DESC LIMIT 500');
print '<h3>Approval Override</h3><div class="cl-scroll"><table class="noborder centpercent cl-table"><tr class="liste_titre"><th>Waktu</th><th>Customer</th><th>Dokumen</th><th>Status</th><th class="right">Nominal</th><th>Alasan</th><th>Approver</th><th>Kedaluwarsa</th></tr>';
foreach($approvals as $r){$name=trim($r->firstname.' '.$r->lastname)?:$r->login;print '<tr class="oddeven"><td>'.clEscape(dol_print_date($db->jdate($r->date_approve),'dayhour')).'</td><td>'.clEscape($r->nom).'</td><td>'.clEscape($r->element_type.' — '.$r->element_ref).'</td><td>'.clEscape(strtoupper($r->status)).'</td><td class="right">'.clMoney($r->document_amount).'</td><td>'.clEscape($r->reason).'</td><td>'.clEscape($name).'</td><td>'.clEscape(dol_print_date($db->jdate($r->date_expiry),'dayhour')).'</td></tr>';}
if(!$approvals)print '<tr><td colspan="8" class="center">Belum ada approval override.</td></tr>';print '</table></div>';clEnd();
